facilityFormItem.valueChangedEventHandler:
var vacationId = functions.getValues()['VacationId'];
ESS.network.sendRequest(`/api/functions/GetVacationKindIdFromVacationId?vacationId=${vacationId}`)
.then(function (vacationKindId) {
  var vacationTable = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'];
  vacationTable.forEach(function (row) {
    functions.setValue('VacationKindId&BeginDate&VacationDuration&EndDateGrid', vacationKindId, row.rowIndex, 'VacationKindId');
  });
});
var initiatorId = JSON.parse(functions.getValues()['PerformerId'])
ESS.network.sendRequest(`/api/functions/GetVacationStatementTemplateId?employeeId=${initiatorId}&isShiftVacation=true`)
.then(function (VacationStatementData) {
  var templateId = JSON.parse(VacationStatementData.TemplateId);
  var docKindId = JSON.parse(VacationStatementData.DocumentKindId);
  functions.setValue('TemplateId', templateId);
  functions.setValue('DocumentKindId', docKindId);
  functions.setValue('IsFromEssAccount', true);
});

facilityFormItem.itemAddingEventHandler:
var vacationId = functions.getValues()['VacationId'];
ESS.network.sendRequest(`/api/functions/GetVacationKindIdFromVacationId?vacationId=${vacationId}`)
.then(function (vacationKindId) {
  var vacationTable = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'];
  vacationTable.forEach(function (row) {
    functions.setValue('VacationKindId&BeginDate&VacationDuration&EndDateGrid', vacationKindId, row.rowIndex, 'VacationKindId');
  });
});

facilityFormItem.itemRemovedEventHandler:
var vacationId = JSON.parse(functions.getValues()['VacationId']);
var rows = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'];
var vacationKindIdsArray = [];
var beginDateArray = [];
var vacationDurationArray = [];
var endDateArray = [];
var VacationsData = '';
rows.forEach(row => {
  if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
    vacationKindIdsArray.push(row.rowValues.VacationKindId);
    var beginDate = `"${row.rowValues.BeginDate}"`;
    beginDateArray.push(beginDate);
    vacationDurationArray.push(row.rowValues.VacationDuration);
    var endDate = `"${row.rowValues.EndDate}"`;
    endDateArray.push(endDate);
    VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
  };
});
functions.setValue('VacationsData', VacationsData);
var vacationIds = [vacationId];
var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
ESS.network.sendRequest(urlTemplate).then(function (errors){
  functions.removeError(window.errorVacations);
  if(errors.length > 0) {
    window.errorVacations = functions.showError(errors);
  }
});
var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=${vacationIds}&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
  if(durationErrors.length > 0) {
    functions.removeError(window.errorDurations);
    window.errorDurations = functions.showError(durationErrors);
  } else {
    functions.removeError(window.errorDurations);
  }
});
var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
ESS.network.sendRequest(urlTemplate).then(function (errors){
  if(errors.length > 0) {
    functions.removeError(window.errorExecutionShift);
    window.errorExecutionShift = functions.showError(errors);
  } else {
    functions.removeError(window.errorExecutionShift);
  }
});

column.valueChangedEventHandler:
var today = new Date();
var yesterday = new Date(today);
yesterday.setDate(today.getDate() -1);
var beginDateValue = formItem.value;
var dateFromControl = new Date(beginDateValue).getTime();
functions.removeError(window.errorDate);
if (dateFromControl < yesterday.getTime()) {
  window.errorDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_BEGIN'));
}
var performerId = JSON.parse(functions.getValues()['PerformerId']);
var durationValue = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationDuration'];
var vacationKindId = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
  return x.rowIndex === formItem.index;
}).rowValues['VacationKindId'];

if (durationValue != null && beginDateValue != null) {
  var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${performerId}&vacationKindId=${vacationKindId}`;
  ESS.network.sendRequest(url)
  .then(function (newEndDateValue) {
    functions.setValue('VacationKindId&BeginDate&VacationDuration&EndDateGrid', newEndDateValue, formItem.index, 'EndDate');
  });
};

            var performerId = JSON.parse(functions.getValues()['PerformerId']);
            var beginDateValue = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['BeginDate'];
            var durationValue = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationDuration'];
            var vacationKindId = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationKindId'];
            
            if (durationValue <= 0) {
              functions.removeError(window.errorId);
              window.errorId = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DURATION'));
            } else {
              functions.removeError(window.errorId);
            }

            if (durationValue != null && beginDateValue != null) {
              var endDate = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
                return x.rowIndex === formItem.index;
              }).rowValues['EndDate'];
              var url = `/api/functions/GetVacationEndDate?dateBegin=${beginDateValue}&duration=${durationValue}&userId=${performerId}&vacationKindId=${vacationKindId}`;
              ESS.network.sendRequest(url)
              .then(function (newEndDateValue) {
                if (new Date(newEndDateValue).getTime() != new Date(endDate).getTime()) {
                  functions.setValue('VacationKindId&BeginDate&VacationDuration&EndDateGrid', newEndDateValue, formItem.index, 'EndDate');
                }
              });
            };

            var initiatorId = JSON.parse(functions.getValues()['PerformerId'])
            var beginDate = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['BeginDate'];
            var endDate = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['EndDate'];
            var vacationKindId = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'].find(function (x) {
              return x.rowIndex === formItem.index;
            }).rowValues['VacationKindId'];
            functions.removeError(window.errorEndDate);
            if (beginDate != null && endDate != null && vacationKindId != null) {
              var url = `/api/functions/DurationInCalendarDaysWithoutHoliday?startDate=${beginDate}&endDate=${endDate}&userId=${initiatorId}&vacationKindId=${vacationKindId}`
              ESS.network.sendRequest(url)
              .then(function (newDuration) {
                if (newDuration <= 0) {
                  window.errorEndDate = functions.showError(ESS.L('@HRPROVACATIONS.ERROR_DATE_END'));
                }
                else {
                  var vacationId = JSON.parse(functions.getValues()['VacationId']);
                  var rows = functions.getValues()['VacationKindId&BeginDate&VacationDuration&EndDateGrid'];
                  var vacationKindIdsArray = [];
                  var beginDateArray = [];
                  var vacationDurationArray = [];
                  var endDateArray = [];
                  var VacationsData = '';
                  rows.forEach(row => {
                    if (row.rowValues.BeginDate != null && row.rowValues.VacationDuration != null) {
                      vacationKindIdsArray.push(row.rowValues.VacationKindId);
                      var beginDate = `"${row.rowValues.BeginDate}"`;
                      beginDateArray.push(beginDate);
                      vacationDurationArray.push(row.rowValues.VacationDuration);
                      var endDate = `"${row.rowValues.EndDate}"`;
                      endDateArray.push(endDate);
                      VacationsData += row.rowValues.VacationKindId + '~' + row.rowValues.BeginDate + '~' + row.rowValues.EndDate +'!';
                    };
                  });
                  functions.setValue('VacationsData', VacationsData);

                  var vacationId = functions.getValues()['VacationId'];
                  var url = `/api/functions/CheckVacationRequiredDuration?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                  ESS.network.sendRequest(url)
                  .then(function (errors) {
                    if (errors.length > 0){
                      functions.removeError(window.errorRequiredDuration);
                      window.errorRequiredDuration = functions.showError(errors);
                    }
                    else{
                      functions.removeError(window.errorRequiredDuration);
                    }
                  });

                  var urlTemplate = `/api/functions/CheckAllVacationShiftDates?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&beginDates=[${beginDateArray}]&durations=[${vacationDurationArray}]&endDates=[${endDateArray}]`;
                  ESS.network.sendRequest(urlTemplate).then(function (errors){
                    if(errors.length > 0) {
                      functions.removeError(window.errorVacations);
                      window.errorVacations = functions.showError(errors);
                    } else {
                      functions.removeError(window.errorVacations);
                    }
                  });
                  if (vacationKindIdsArray.length > 0) {
                    var urlTemplate = `/api/functions/CheckShiftingVacationsDurations?vacationIds=[${vacationId}]&vacationKindIds=[${vacationKindIdsArray}]&durations=[${vacationDurationArray}]`;
                    ESS.network.sendRequest(urlTemplate).then(function (durationErrors){
                      if(durationErrors.length > 0) {
                        functions.removeError(window.errorDurations);
                        window.errorDurations = functions.showError(durationErrors);
                      } else {
                        functions.removeError(window.errorDurations);
                      }
                    });
                  };
                  var urlTemplate = `/api/functions/CheckExecutionShiftVacations?vacationIds=[${vacationId}]`;
                  ESS.network.sendRequest(urlTemplate).then(function (errors){
                    if(errors.length > 0) {
                      functions.removeError(window.errorExecutionShift);
                      window.errorExecutionShift = functions.showError(errors);
                    } else {
                      functions.removeError(window.errorExecutionShift);
                    }
                  });
                }
              });
            }
            
            var url = `/api/functions/CheckVacationHasHoliday?periodBegin=${beginDate}&periodEnd=${endDate}&employeeId=${initiatorId}&vacationKindId=${vacationKindId}`;
            ESS.network.sendRequest(url)
            .then(function (warning) {
              if(warning.length > 0)
                ESS.toasts.showToast(warning, 'warning', true);
            });

facility.openingEventHandler:
ESS.network.sendRequest(`/api/functions/GetConfirmationVacationOnRework?assignmentId=${functions.getValues().AssignmentId}`)
.then(function (approvalVacationOnRework) {            
  functions.setValue('VacationId', approvalVacationOnRework.VacationId);
  resolve();
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
  reject();
});
